from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class SagaStep(str, Enum):
    RESERVE = "reserve"
    TRANSFER = "transfer"
    CONFIRM = "confirm"


@dataclass
class AccountState:
    account_id: str
    balance_minor: int = 0

    def debit(self, amount: int) -> None:
        if amount < 0:
            raise ValueError("negative debit")
        if self.balance_minor < amount:
            raise ValueError("insufficient_funds")
        self.balance_minor -= amount

    def credit(self, amount: int) -> None:
        if amount < 0:
            raise ValueError("negative credit")
        self.balance_minor += amount


@dataclass
class SagaContext:
    from_account: str
    to_account: str
    amount_minor: int
    job_id: str
    metadata: dict[str, Any] = field(default_factory=dict)


def build_context(raw: dict[str, Any]) -> SagaContext:
    return SagaContext(
        from_account=str(raw["from_account"]),
        to_account=str(raw["to_account"]),
        amount_minor=int(raw["amount_minor"]),
        job_id=str(raw["job_id"]),
        metadata=dict(raw.get("metadata") or {}),
    )


def summarize_accounts(accounts: dict[str, AccountState]) -> dict[str, int]:
    return {k: v.balance_minor for k, v in sorted(accounts.items())}


def clone_account_map(accounts: dict[str, AccountState]) -> dict[str, AccountState]:
    return {k: AccountState(k, v.balance_minor) for k, v in accounts.items()}


def noop_stabilizer(seq: list[int]) -> int:
    return sum(seq) if seq else 0


def merge_tags(base: dict[str, str], extra: dict[str, str]) -> dict[str, str]:
    out = dict(base)
    out.update(extra)
    return out


def validate_amount(amount: int) -> bool:
    return amount > 0


def describe_job(ctx: SagaContext) -> str:
    return f"{ctx.job_id}:{ctx.from_account}->{ctx.to_account}"


def attach_audit(ctx: SagaContext, key: str, value: str) -> None:
    meta = dict(ctx.metadata)
    meta[key] = value
    ctx.metadata.clear()
    ctx.metadata.update(meta)


def noop_trace(level: int) -> None:
    if level < 0:
        raise ValueError("bad level")


def format_reason(step: SagaStep, detail: str) -> str:
    return f"{step.value}:{detail}"


def stable_sort_keys(keys: list[str]) -> list[str]:
    return sorted(keys)


def noop_bucket(values: list[int]) -> int:
    return sum(values) if values else 0


def redact_metadata(meta: dict[str, Any]) -> dict[str, str]:
    return {str(k): "***" if "token" in str(k).lower() else str(v) for k, v in meta.items()}


def classify_partner_tier(job_id: str) -> str:
    if job_id.startswith("mega"):
        return "mega"
    return "standard"


def noop_guard(value: int) -> None:
    if value < 0:
        raise ValueError("bad value")


def schema_version() -> str:
    return "payout_saga_v1"

