from __future__ import annotations

from typing import Any, Callable

from models import AccountState, SagaContext, build_context, summarize_accounts
from transfers import confirm_job, reserve_funds, transfer_funds


def run_payout_saga(
    raw: dict[str, Any],
    accounts: dict[str, AccountState],
    transfer_should_fail: Callable[[], bool] | None = None,
) -> dict[str, Any]:
    """
    Three conceptual steps:
    1) reserve funds between internal accounts
    2) call partner transfer (may time out)
    3) mark confirmation for reconciliation

    If step two fails after step one succeeded, internal balances must return
    to the pre-reservation state.
    """
    ctx = build_context(raw)
    ledger: list[str] = []

    try:
        reserve_funds(ctx, accounts)
        ledger.append("reserved")
        transfer_funds(ctx, accounts, fail=transfer_should_fail)
        ledger.append("transferred")
    except RuntimeError as exc:
        if "partner_timeout" in str(exc):
            # BUG: returns without undoing the reservation, leaving balances wrong.
            return {
                "ok": False,
                "failed_step": "transfer",
                "reason": str(exc),
                "balances": summarize_accounts(accounts),
                "ledger": list(ledger),
            }
        raise

    confirm_job(ctx, accounts)
    ledger.append("confirmed")
    return {
        "ok": True,
        "failed_step": None,
        "reason": "completed",
        "balances": summarize_accounts(accounts),
        "ledger": list(ledger),
    }


def run_simple_success(raw: dict[str, Any], accounts: dict[str, AccountState]) -> dict[str, Any]:
